window.ScripturaLexicons.BDAG_PART_0280 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-01\" data-source=\"BDAG\" data-search=\"πέπρακα remissão verbal ver πιπράσκω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέπρακα</td><td>remissão verbal</td><td>ver πιπράσκω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-02\" data-source=\"BDAG\" data-search=\"πέπραμαι remissão verbal ver πιπράσκω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέπραμαι</td><td>remissão verbal</td><td>ver πιπράσκω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-03\" data-source=\"BDAG\" data-search=\"πέπραχα remissão verbal ver πράσσω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέπραχα</td><td>remissão verbal</td><td>ver πράσσω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-04\" data-source=\"BDAG\" data-search=\"πέπτωκα remissão verbal ver πίπτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέπτωκα</td><td>remissão verbal</td><td>ver πίπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-05\" data-source=\"BDAG\" data-search=\"πέπωκα remissão verbal ver πίνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέπωκα</td><td>remissão verbal</td><td>ver πίνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-06\" data-source=\"BDAG\" data-search=\"περ partícula enclítica intensificação e ampliação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περ</td><td>partícula enclítica</td><td>intensificação e ampliação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-07\" data-source=\"BDAG\" data-search=\"Περαία, ας, nome geográfico; remissão Pereia; ver πέραν bγ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Περαία, ας,</td><td>nome geográfico; remissão</td><td>Pereia; ver πέραν bγ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-08\" data-source=\"BDAG\" data-search=\"περαιτέρω advérbio comparativo mais adiante; além; adicionalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περαιτέρω</td><td>advérbio comparativo</td><td>mais adiante; além; adicionalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-09\" data-source=\"BDAG\" data-search=\"πέραν advérbio e preposição do outro lado; além; Pereia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέραν</td><td>advérbio e preposição</td><td>do outro lado; além; Pereia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-10\" data-source=\"BDAG\" data-search=\"πέρας, ατος, τό substantivo neutro; uso adverbial limite; extremidade; fim; finalmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πέρας, ατος, τό</td><td>substantivo neutro; uso adverbial</td><td>limite; extremidade; fim; finalmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-11\" data-source=\"BDAG\" data-search=\"Πέργαμος, ου, ἡ topônimo Pérgamo, cidade da Mísia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πέργαμος, ου, ἡ</td><td>topônimo</td><td>Pérgamo, cidade da Mísia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-12\" data-source=\"BDAG\" data-search=\"Πέργη, ης, ἡ topônimo feminino Perge, cidade da Panfília BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πέργη, ης, ἡ</td><td>topônimo feminino</td><td>Perge, cidade da Panfília</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-13\" data-source=\"BDAG\" data-search=\"περί preposição sobre; acerca de; por; ao redor de; aproximadamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περί</td><td>preposição</td><td>sobre; acerca de; por; ao redor de; aproximadamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-14\" data-source=\"BDAG\" data-search=\"περιάγω verbo levar consigo; conduzir; percorrer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιάγω</td><td>verbo</td><td>levar consigo; conduzir; percorrer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-15\" data-source=\"BDAG\" data-search=\"περιαιρέω verbo retirar; remover; fazer cessar; eliminar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιαιρέω</td><td>verbo</td><td>retirar; remover; fazer cessar; eliminar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-16\" data-source=\"BDAG\" data-search=\"περιάπτω verbo acender; atear fogo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιάπτω</td><td>verbo</td><td>acender; atear fogo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-17\" data-source=\"BDAG\" data-search=\"περιαστράπτω verbo reluzir ao redor; brilhar intensamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιαστράπτω</td><td>verbo</td><td>reluzir ao redor; brilhar intensamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-18\" data-source=\"BDAG\" data-search=\"περιβάλλω verbo cercar; vestir; envolver; impor sofrimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιβάλλω</td><td>verbo</td><td>cercar; vestir; envolver; impor sofrimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-19\" data-source=\"BDAG\" data-search=\"περιβλέπω verbo médio olhar em volta; observar; procurar alguém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιβλέπω</td><td>verbo médio</td><td>olhar em volta; observar; procurar alguém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0280-20\" data-source=\"BDAG\" data-search=\"περιβόητος, ον adjetivo célebre; muito conhecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">περιβόητος, ον</td><td>adjetivo</td><td>célebre; muito conhecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0280-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέπρακα</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέπρακα</span>: veja <span class=\"greek\">πιπράσκω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέπραμαι</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέπραμαι</span>: veja <span class=\"greek\">πιπράσκω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέπραχα</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέπραχα</span>: veja <span class=\"greek\">πράσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέπτωκα</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέπτωκα</span>: veja <span class=\"greek\">πίπτω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέπωκα</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέπωκα</span>: veja <span class=\"greek\">πίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περ</h1><div class=\"entry-meta\"><span>partícula enclítica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περ</span>, partícula enclítica, com força intensiva e extensiva (B-D-F §107; Rob. 1153); vejam-se as palavras compostas com ela: <span class=\"greek\">διόπερ</span>, <span class=\"greek\">ἐάνπερ</span> (veja <span class=\"greek\">ἐάν</span> 1c<span class=\"greek\">γ</span>), <span class=\"greek\">εἴπερ</span> (veja <span class=\"greek\">εἰ</span> 6l), <span class=\"greek\">ἐπειδήπερ</span>, <span class=\"greek\">ἐπείπερ</span>, <span class=\"greek\">ἤπερ</span> (veja <span class=\"greek\">ἤ</span> 2e<span class=\"greek\">β</span>), <span class=\"greek\">καθάπερ</span>, <span class=\"greek\">καίπερ</span>, <span class=\"greek\">ὅσπερ</span> (veja <span class=\"greek\">ὅς</span> 1j<span class=\"greek\">ε</span>), <span class=\"greek\">ὥσπερ</span> (<span class=\"greek\">ὡσπερεί</span>).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Περαία, ας,</h1><div class=\"entry-meta\"><span>nome geográfico; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Περαία</span>, <span class=\"greek\">ας</span>: veja <span class=\"greek\">πέραν</span> b<span class=\"greek\">γ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περαιτέρω</h1><div class=\"entry-meta\"><span>advérbio comparativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περαιτέρω</span> (<span class=\"greek\">πέρα</span> «além, mais distante»; Aeschyl., Thu. e outros; Jos., Bell. 4, 107, Ant. 18, 301; 19, 141; BGU 372 II, 12 [154 d.C.]), advérbio de <span class=\"greek\">περαίτερος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span>, comparativo de <span class=\"greek\">πέρα</span>: relativo a algo adicional ao que já se expressou no contexto, mais adiante, além, adicionalmente; <span class=\"greek\">εἰ</span> <span class=\"greek\">δέ</span> <span class=\"greek\">τι</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐπιζητεῖτε</span> «se há algo mais que desejais saber» (cf. Pla., Phd. 107b <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ζητήσετε</span> <span class=\"greek\">περαιτέρω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:39</a> (variante textual <span class=\"greek\">περὶ</span> <span class=\"greek\">ἑτέρων</span>).—DELG s.v. <span class=\"greek\">πέρα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέραν</h1><div class=\"entry-meta\"><span>advérbio e preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέραν</span>, advérbio de lugar (Hom. [<span class=\"greek\">πέρην</span>] e outros; inscrições, papiros, LXX), marcador de uma posição oposta a outra coisa, com espaço intermediário, do outro lado.<br><br>ⓐ Funciona como advérbio e, substantivado com artigo, <span class=\"greek\">τὸ</span> <span class=\"greek\">πέραν</span>, «a margem ou terra do outro lado» (X., An. 4, 3, 11; Sb 7252, 19): <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πέραν</span> (Pla.; Polyb.; SIG 495, 84; 619, 27; 709, 6; BGU 1022, 25; 1 Macc 9:48) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:18</a>, 28; 14:22; 16:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:35</a>; 5:21; 6:45; 8:13.<br><br>ⓑ Funciona como preposição com genitivo (B-D-F §184; Rob. 646).<br><br><span class=\"greek\">α</span>. Responde à pergunta «para onde?»: <span class=\"greek\">ἀπῆλθεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span> «Jesus foi para o outro lado do lago» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:1</a>. <span class=\"greek\">ἤρχοντο</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θαλάσσης</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Καφαρναούμ</span> «vinham ao outro lado do lago, a Cafarnaum» v. 17. Cf. 10:40; 18:1.<br><br><span class=\"greek\">β</span>. Responde à pergunta «onde?»: <span class=\"greek\">ταῦτα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Βηθανίᾳ</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span> «isto aconteceu em Betânia, do outro lado do Jordão» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:28</a> (PParker, JBL 74, ’55, 257–61 [não «além» = oeste, mas «do outro lado, em frente» = leste]). <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅρια</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰουδαίας</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:1</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:26</a>; 6:22, 25.—<span class=\"greek\">πέραν</span> com genitivo também pode ser empregado com artigo como substantivo (X., An. 3, 5, 2 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποταμοῦ</span>; Jos., Ant. 7, 198): <span class=\"greek\">ἦλθον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θαλάσσης</span> «chegaram à (terra na) outra margem do lago» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:1</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:22</a>.—A reconstrução indevida <span class=\"greek\">τ</span>[<span class=\"greek\">ὰ</span> <span class=\"greek\">ὄντα</span>]| <span class=\"greek\">πέρ̣αν</span> <span class=\"greek\">τῶν</span> [<span class=\"greek\">ἀ</span>]<span class=\"greek\">κο</span>[<span class=\"greek\">ῶ</span>]<span class=\"greek\">ν</span> em Ox 1081, 6f não leva em conta a cópia copta; vejam-se <span class=\"greek\">ἀκούω</span> 7 e <span class=\"greek\">ἀπέραντος</span>.<br><br><span class=\"greek\">γ</span>. Em diversas passagens, <span class=\"greek\">πέραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span> (Is 8:23; cf. Jos., Ant. 12, 222) funciona como nome indeclinável do território do outro lado (oriental) do Jordão, isto é, Pereia: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Γαλιλαίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἰουδαίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span> «da Galileia, Judeia e Pereia» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:25</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰδουμαίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:8</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:15</a> (Is 8:23); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:1</a> (variante textual <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πέραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span>).—<span class=\"greek\">Περαία</span>, <span class=\"greek\">ας</span> (frequente em Joseph.) aparece em nossa literatura somente como variante textual: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:17</a>. (A expressão de modo algum se limita à Palestina: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">περαίᾳ</span> em Appian, Bell. Civ. 2, 42 §168 refere-se à terra do outro lado do rio. Além disso, a região da parte continental da Cária em frente à ilha de Rodes também se chamava Pereia: Appian, op. cit. 4, 72 §305; também Livy 32, 33; 33, 18.)—Meistermann (<span class=\"greek\">Καφαρναούμ</span>, final) 93ff. DELG s.v. <span class=\"greek\">πέρα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέρας, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro; uso adverbial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πέρας</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (cf. <span class=\"greek\">πεῖραρ</span> «fim, limite»; Aeschyl.+), «limite, fim».<br><br>① Ponto determinado que constitui a extremidade mais distante de um espaço, fim, limite, fronteira. No plural, <span class=\"greek\">τὰ</span> <span class=\"greek\">πέρατα</span> «fim, limite, fronteira; extremidades, limites»: <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> «da terra» (Alcaeus [c. 600 a.C.] 50, 1 Diehl2; Thu. 1, 69, 5; X., Ages. 9, 4; IPontEux I, 39, 26f (<span class=\"greek\">μέχρι</span>) <span class=\"greek\">περάτων</span> <span class=\"greek\">γῆς</span>; Ps 2:8; 21:28; Da 4:21; En 1:5; 31:2; Philo; Jos., Bell. 4, 262; TestNapht 6:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:31</a> (acerca de ambas as passagens, cf. Apollon. Rhod. 2, 165 <span class=\"greek\">ἐκ</span> <span class=\"greek\">περάτων</span>; 573–76); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:33</a> D (Ps 2:8); 1 Cl 36:4 (Ps 2:8); IRo 6:1; Hs 8, 3, 2; D 9:4. <span class=\"greek\">τὰ</span> <span class=\"greek\">πέρατα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκουμένης</span> (Diod S 3, 53, 1 <span class=\"greek\">τὰ</span> <span class=\"greek\">πέρατα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκουμένης</span>; 1, 19, 6 <span class=\"greek\">τὸ</span> <span class=\"greek\">πέρας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>.; Jos., Ant. 8, 116; cf. ApcEsdr 3:6 p. 27, 12 Tdf.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:18</a> (Ps 18:5). Também <span class=\"greek\">τὰ</span> <span class=\"greek\">πέρατα</span>, absolutamente, no mesmo sentido (Vett. Val. 226, 18; Philo, Leg. ad Gai. 18; 173; Ps 64:9): <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπίσκοποι</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πέρατα</span> <span class=\"greek\">ὁρισθέντες</span> «os supervisores/bispos designados para as terras mais distantes» IEph 3:2.—JGeyer, VetusT 20, ’70, 87–90, em resposta a MTreves, ibid. 19, ’69, 235.<br><br>② Ponto terminal de um processo, fim, conclusão (Aeschyl., Pers. 632 <span class=\"greek\">τῶν</span> <span class=\"greek\">κακῶν</span>; Demosth. 18, 97 <span class=\"greek\">πέρας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θάνατος</span>; Polyb. 5, 31, 2; 7, 5, 5; Epict. 3, 26, 37; 4, 1, 106; OGI 669, 40; PGiss 25, 7; BGU 1019, 7; POxy 237 VIII, 16; 1 Esdr 9:17; 2 Macc 5:8; 3 Macc 5:5; TestAbr A 1 p. 77, 11 [Stone p. 2] <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span> <span class=\"greek\">πέρας</span>; Philo, Op. M. 150 e outros; Jos., Bell. 7, 157, Ant. 7, 374; Just., D. 137, 4 <span class=\"greek\">π</span>. <span class=\"greek\">ποιεῖσθαι</span>; Tat. 12, 4 <span class=\"greek\">π</span>. <span class=\"greek\">λαβών</span>): <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀντιλογίας</span> <span class=\"greek\">πέρας</span> «fim de toda disputa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:16</a>.<br><br>③ Como advérbio, <span class=\"greek\">πέρας</span>, marcador de algo acrescentado a uma sequência, finalmente, em conclusão, além disso (desde Aeschin. 1, 61; Polyb. 2, 55, 6; Alciphron 4, 17, 3; Manetho: 609 Fgm. 8 [77] Jac. [em Jos., C. Ap. 1, 77]; Jos., Bell. 7, 393, Ant. 16, 352): <span class=\"greek\">π</span>. <span class=\"greek\">γέ</span> <span class=\"greek\">τοι</span> B 5:8; B 10:2; B 12:6; B 15:6, B 8; B 16:3; <span class=\"greek\">π</span>. <span class=\"greek\">γοῦν</span> MPol 16:1.—DELG s.v. <span class=\"greek\">πεῖραρ</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πέργαμος, ου, ἡ</h1><div class=\"entry-meta\"><span>topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πέργαμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">πύργος</span> «torre»; X., Hell. 3, 1, 6; Paus. 7, 16, 1) ou <span class=\"greek\">Πέργαμον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Polyb. 4, 48, 11; Diod S 28, 5; Strabo 13, 4, 1; 2; Appian, Mithrid. 52 §210; Jos., Bell. 1, 425 <span class=\"greek\">τὸ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">Μυσίαν</span> <span class=\"greek\">Πέργαμον</span>.—No NT, como em muitos outros casos [por exemplo, OGI índice II p. 595a], não se pode determinar o gênero), Pérgamo, importante cidade da Mísia, no noroeste da Ásia Menor. Era centro de diversos cultos: Zeus Soter, Asclepius Soter e Athena Nicephorus possuíam ali templos célebres. Também era um centro do culto imperial; já em 29 a.C., a assembleia provincial ergueu um santuário a Augusto e Roma. Os cristãos parecem ter sido perseguidos ali desde época antiga (veja <span class=\"greek\">Ἀντιπᾶς</span>). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:11</a>; 2:12.—Altertümer von Pergamon I–VIII 1885–1930; deste conjunto, vol. VIII=IPergamon; EPontremoli e MCollignon, Pergame 1900; VSchultze, Altchristliche Städte u. Landschaften II 2, 1926; AvSalis, D. Altar v. P. 1912; Pauly-W. XIX 1235–63; Kl. Pauly IV 626–31; BHHW III 1420f; PECS 688–92 (bibliografia).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πέργη, ης, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πέργη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Callim., Hymn to Diana 187; Strabo 14, 4, 2; Philostrat., V. S. 2, 6; inscrições; moedas), Perge, cidade da Panfília, próxima à costa meridional da Ásia Menor. Visitada por Paulo em sua assim chamada primeira viagem missionária <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:14</a>; 14:25. <span class=\"greek\">Π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Παμφυλίας</span> 13:13.—WRuge, Pauly-W. XIX 694–704; Kl. Pauly IV 631f; BHHW III 1421; PECS 692f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περί</h1><div class=\"entry-meta\"><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περί</span> (Hom.+), preposição com genitivo e acusativo; em nossa literatura não ocorre com dativo (B-D-F §203; Rob. 617; veja a bibliografia s.v. <span class=\"greek\">ἀνά</span>, início), literalmente «ao redor de».<br><br>① Com genitivo, para designar o objeto ou pessoa a que determinada atividade ou, especialmente, um processo interior se refere ou com o qual se relaciona, acerca de, sobre.<br><br>ⓐ Após verbos que designam expressão oral ou escrita, recepção dessa expressão, ação mental, conhecimento, pensamento, reconhecimento etc.: acerca de, sobre; vejam-se os verbetes <span class=\"greek\">ἀκούω</span> 1c e 3c, <span class=\"greek\">ἀναγγέλλω</span> 2, final, <span class=\"greek\">ἀπαγγέλλω</span> 1, <span class=\"greek\">ἀπολογέομαι</span>, <span class=\"greek\">γνωρίζω</span> 1, <span class=\"greek\">γογγύζω</span>, <span class=\"greek\">γράφω</span> 2c, <span class=\"greek\">δηλόω</span>, <span class=\"greek\">διαβεβαιόομαι</span>, <span class=\"greek\">διαλέγομαι</span> 1, <span class=\"greek\">διδάσκω</span> 2d, <span class=\"greek\">διηγέομαι</span>, <span class=\"greek\">εἶπον</span> 1a, <span class=\"greek\">ἐντέλλω</span>, <span class=\"greek\">ἐπιστέλλω</span>, <span class=\"greek\">κατηχέω</span>, <span class=\"greek\">λαλέω</span> 2a<span class=\"greek\">γ</span>, <span class=\"greek\">λέγω</span> 1b<span class=\"greek\">δ</span>; <span class=\"greek\">λόγον</span> <span class=\"greek\">αἰτεῖν</span>, <span class=\"greek\">ἀποδιδόναι</span>, <span class=\"greek\">διδόναι</span>, <span class=\"greek\">ποιεῖσθαι</span> (veja <span class=\"greek\">λόγος</span> 2a); <span class=\"greek\">μαρτυρέω</span> 1b, <span class=\"greek\">μνημονεύω</span> 1c, <span class=\"greek\">ὁμιλέω</span>, <span class=\"greek\">πυνθάνομαι</span>, <span class=\"greek\">προκαταγγέλλω</span>, <span class=\"greek\">προφητεύω</span>, <span class=\"greek\">ὑπομιμνῄσκω</span>, <span class=\"greek\">χρηματίζομαι</span>; <span class=\"greek\">ἀγνοέω</span> 1a, <span class=\"greek\">ἀπορέω</span>, <span class=\"greek\">ἐπινοέω</span>, <span class=\"greek\">ἐπίσταμαι</span> 2, <span class=\"greek\">οἶδα</span> 1h, <span class=\"greek\">πέπεισμαι</span> (veja <span class=\"greek\">πείθω</span> 4), <span class=\"greek\">πιστεύω</span> 1a<span class=\"greek\">β</span>. Também se emprega com substantivos relacionados a esses verbos ou com verbos de significação semelhante: <span class=\"greek\">ἀπολογία</span> 2a, <span class=\"greek\">γογγυσμός</span>; <span class=\"greek\">διήγησις</span>, <span class=\"greek\">εὐαγγέλιον</span>, <span class=\"greek\">ἦχος</span> 2, <span class=\"greek\">πρόφασις</span>, <span class=\"greek\">φήμη</span>; vejam-se os respectivos verbetes. <span class=\"greek\">γινώσκω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:17</a>. <span class=\"greek\">συμφωνέω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:19</a>. <span class=\"greek\">τί</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">δοκεῖ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>; «que pensais a respeito do Cristo?» 22:42.<br><br>ⓑ Após verbos que expressam consideração, pergunta, exame, acusação, julgamento, censura, punição, louvor etc.: por causa de, em razão de, por, acerca de. Vejam-se os verbetes <span class=\"greek\">ἀποστοματίζω</span>, <span class=\"greek\">ἀπορέω</span>, <span class=\"greek\">διαπορέω</span>, <span class=\"greek\">ἐγκαλέω</span>, <span class=\"greek\">εἶδον</span> (3: deliberar a respeito de), <span class=\"greek\">ἐκζητέω</span> 1, <span class=\"greek\">ἐλέγχω</span> 2 e 3, <span class=\"greek\">ἐξετάζω</span> 1 e 2b, <span class=\"greek\">ἐπερωτάω</span> 1a, <span class=\"greek\">ἐπιζητέω</span> 1b, <span class=\"greek\">ἐρωτάω</span> 1, <span class=\"greek\">ζητέω</span> 2, <span class=\"greek\">κατηγορέω</span>, <span class=\"greek\">παραμυθέομαι</span>.—<span class=\"greek\">διαλογίζομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:15</a>. <span class=\"greek\">κρίνω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:26</a>. <span class=\"greek\">λιθάζω</span> 10:33. <span class=\"greek\">θεὸν</span> <span class=\"greek\">αἰνέω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:37</a>. <span class=\"greek\">περὶ</span> <span class=\"greek\">οὗ</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">κατήγοροι</span> <span class=\"greek\">οὐδεμίαν</span> <span class=\"greek\">αἰτίαν</span> <span class=\"greek\">ἔφερον</span> «seus acusadores não apresentaram nenhuma acusação desse tipo contra ele» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:18</a> (BWeiss e Preuschen ligam <span class=\"greek\">περὶ</span> <span class=\"greek\">οὗ</span> a <span class=\"greek\">σταθέντες</span>, que vem imediatamente em seguida, e entendem «ao redor dele», «perto dele» [<span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> com esse sentido IG XIV, 2508, 4]).—Veja-se também <span class=\"greek\">ζήτημα</span>.<br><br>ⓒ Após verbos que designam emoção. Vejam-se <span class=\"greek\">ἀγανακτέω</span>, <span class=\"greek\">θαυμάζω</span> 1a<span class=\"greek\">β</span>, <span class=\"greek\">καυχάομαι</span>, <span class=\"greek\">σπλαγχνίζομαι</span>.<br><br>ⓓ Após verbos que expressam cuidado (por alguém ou alguma coisa). Vejam-se <span class=\"greek\">μέλει</span> 1b, <span class=\"greek\">μεριμνάω</span>, <span class=\"greek\">προβλέπω</span>.<br><br>ⓔ Após outros verbos e expressões, principalmente no sentido de com relação a, com referência a, em relação a, no que diz respeito a: <span class=\"greek\">εὐλογεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:20</a>. <span class=\"greek\">ἀναβαίνειν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζητήματος</span> «subir para tratar da questão» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:2</a>. <span class=\"greek\">ἐντολὰς</span> <span class=\"greek\">λαμβάνειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:10</a>. <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">ἔχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:37</a> (veja <span class=\"greek\">ἐξουσία</span> 1). <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">εὐοδοῦσθαι</span> «prosperar em todos os aspectos» 3J 2 (<span class=\"greek\">περὶ</span> <span class=\"greek\">π</span>. = «em todos os aspectos»: Pla., Gorg. 23, 467d.—Outros entendem «acima de tudo»; cf. Il. 1, 287; 21, 566).<br><br>ⓕ Com certos verbos e substantivos como «pedir», «orar», «oração» etc., <span class=\"greek\">περί</span> introduz a pessoa ou coisa em cujo interesse se faz a petição. Assim, substitui <span class=\"greek\">ὑπέρ</span> (B-D-F §229, 1; Rob. 618; WSchulze, Zeitschr. für vergl. Sprachforschung 44, 1911, 359: Callim., Epigr. 55, 3.—SIG 1170, 30 <span class=\"greek\">περὶ</span> <span class=\"greek\">τούτου</span> <span class=\"greek\">παρεκάλεσα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; POxy 1298, 4; 1494, 6; JosAs 28:5 <span class=\"greek\">ἐξιλάσομαι</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὑμῶν</span>; EpArist 273): por, em favor de. Vejam-se <span class=\"greek\">δέομαι</span> b, <span class=\"greek\">δέησις</span>, <span class=\"greek\">ἐρωτάω</span> 2, <span class=\"greek\">παρακαλέω</span> 3. <span class=\"greek\">προσεύχεσθαι</span> (Gen 20:7; 1 Km 7:5; 2 Macc 1:6; 15:14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:3</a> (variante textual <span class=\"greek\">ὑπέρ</span>); 4:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:11</a>; 3:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:18</a>. <span class=\"greek\">προσευχὴ</span> <span class=\"greek\">γίνεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:5</a>. <span class=\"greek\">Παῦλος</span> <span class=\"greek\">ἐσταυρώθη</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὑμῶν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:13</a>, variante textual (em lugar de <span class=\"greek\">ὑπέρ</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἐκχυννόμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:28</a> (cf. Nicol. Dam.: 90 Fgm. 730, 29 p. 415, 29 Jac. <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">διαδόχων</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἅπαν</span> … <span class=\"greek\">παθεῖν</span>). <span class=\"greek\">ἀγῶνα</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:1</a>, variante textual (em lugar de <span class=\"greek\">ὑπέρ</span>).<br><br>ⓖ Quando empregado com <span class=\"greek\">ἁμαρτία</span>, o vocábulo «por» assume o sentido de remover, expiar: <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτίας</span> (Num 8:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:3</a> (diferentemente TThornton, JTS 22, ’71, 515–17). <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">δόντος</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:4</a>, variante textual (em lugar de <span class=\"greek\">ὑπέρ</span>; CBreytenbach, Versöhnung ’89, 197). <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">ἔπαθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:18</a> (variante textual <span class=\"greek\">ἀπέθανεν</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:3c</a>. <span class=\"greek\">προσφορὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτίας</span> 10:18. <span class=\"greek\">θυσία</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτιῶν</span> v. 26. <span class=\"greek\">εἰσφέρεται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτίας</span> 13:11. <span class=\"greek\">τὸ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁμαρτίας</span> (isto é, <span class=\"greek\">προσφερόμενον</span>) «a oferta pelo pecado» (Lev 6:23; 14:19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:6</a>, 8 (ambos Ps 39:7).<br><br>ⓗ <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, absolutamente no início de uma frase: acerca de, com referência a (GrBar 8:6; Just., A I, 15, 1 e outros; SIG 736, 1; PEleph 13, 4f; BGU 246, 13; 17; 1097, 5 [c. 50 d.C.]; 1095, 9 [57 d.C.]): <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> (=<span class=\"greek\">περὶ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἃ</span>) <span class=\"greek\">ἐγράψατε</span> «acerca das coisas que escrevestes (a mim)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:1</a> (veja <span class=\"greek\">γράφω</span> 2c). Cf. 8:1; 16:1, 12. Em outras passagens aparentemente semelhantes, deve ser relacionado ao verbo seguinte: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:31</a>; 24:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:26</a>; 13:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:25</a>; 8:4; 12:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:9</a>; 5:1. (Cf. a formulação das respostas de Cláudio em PLond 1912; sobre o uso retórico de Paulo, cf. Demosth. 7, 1; 14; 18; 30; 39; MMitchell NovT 31, ’89, 229–56.)<br><br>ⓘ Com artigo, <span class=\"greek\">τὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> «o que diz respeito a alguém ou alguma coisa», suas circunstâncias, situação, condição (X., An. 2, 5, 37 <span class=\"greek\">ὅπως</span> <span class=\"greek\">μάθοι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Προξένου</span>; Sir 19:30; TestJob 41:3; JosAs 19:2; GrBar 4:12; Just., A I, 33, 5; Tat. 36, 2): <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">Ἰησοῦ</span>, «os relatos sobre Jesus», acerca de seus milagres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:27</a>; das experiências de sua paixão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:19</a>; da pregação acerca de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:25</a>; cf. 28:31. <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἑαυτοῦ</span> (<span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">ἐμοῦ</span>, <span class=\"greek\">ἐμαυτοῦ</span>, <span class=\"greek\">ἡμῶν</span>, <span class=\"greek\">ὑμῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:11</a>, 15; 24:10; 28:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:27</a>; 2:19f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:8</a>.—<span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> «as coisas concernentes ao Reino de Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:3</a>; 19:8 (variante textual sem artigo). <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span> 24:22 (<span class=\"greek\">ὁδός</span> 3c).<br><br>② Com acusativo, geralmente referente à posição, mais que às considerações mentais ou emocionais, como no uso do genitivo, ao redor de, acerca de.<br><br>ⓐ De lugar: ao redor de, em torno de, perto de (TestJob 40:6 <span class=\"greek\">περί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">φάτνην</span>; 12 <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span>; Ath. 25, 1 <span class=\"greek\">ἄγγελοι</span> … <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀέρα</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>).<br><br><span class=\"greek\">α</span>. (Por todos os lados) ao redor de: <span class=\"greek\">ἕως</span> <span class=\"greek\">ὅτου</span> <span class=\"greek\">σκάψω</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτήν</span> «até que eu cave (ao redor de toda) ela» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:8</a>. <span class=\"greek\">περιαστράψαι</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἐμέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:6b</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">παρθένοι</span> <span class=\"greek\">ἑστηκυῖαι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πύλην</span> «as virgens que estavam em torno da porta» Hs 9, 3, 2.<br><br><span class=\"greek\">β</span>. Parte do corpo em torno da qual alguma coisa é colocada (Heraclid. Pont. Fgm. 55 W. <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέτωπον</span>; PsSol 2:20 <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span>; TestJob 46:9 <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στῆθος</span>; JosAs 3:9 <span class=\"greek\">περὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span>): um cinto <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀσφύν</span> «em torno da cintura» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:6</a> (JosAs 14:16); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:6</a>. Uma pedra de moinho <span class=\"greek\">περίκειται</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:2</a> (JosAs 18:5); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a>.<br><br><span class=\"greek\">γ</span>. Lugares próximos: <span class=\"greek\">αἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτὰς</span> <span class=\"greek\">πόλεις</span> «as cidades próximas delas» (Sodoma e Gomorra) Jd 7. <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> «a região ao redor do lugar» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:7</a> (Diod S 1, 50, 6 <span class=\"greek\">τὰ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">Μέμφιν</span>; Strabo 12, 7, 3). Sem artigo: <span class=\"greek\">περὶ</span> <span class=\"greek\">Τύρον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Σιδῶνα</span> «as proximidades de Tiro e Sidom» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:8</a>.<br><br><span class=\"greek\">δ</span>. Pessoas que estão de pé, sentadas, trabalhando ou permanecendo perto de alguém: <span class=\"greek\">ὄχλον</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:18</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:14</a>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">καθημένους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:34</a>; cf. v. 32. <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτόν</span> «os que estavam ao redor dele, seus seguidores» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:49</a>. A pessoa central do grupo pode estar incluída: <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Παῦλον</span> «Paulo e seus companheiros» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:13</a>; 21:8, variante textual. <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Πέτρον</span> «Pedro e os que estavam com ele», final breve de Marcos; GHb 356, 38f= ISm 3:2; cf. GHb 22, 39 (Pla., Thu., X.; Diod S 11, 40, 3; 11, 61, 3 <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Κίμωνα</span>=Címon e seus homens; inscrições, papiros; 2 Macc 1:33; 8:30; 4 Macc 2:19; JosAs 26:5; Jos., Bell. 5, 10, Ant. 18, 354 e outros; Tat. 36, 1 e outros; B-D-F §228; Rob. 620). <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κεντυρίωνα</span> «o centurião e seus homens» GPt 11:45. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Μάρθαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Μαριάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:19</a>, variante textual, provavelmente refere-se apenas às duas irmãs: «a Marta e Maria» (cf. Phalaris, Ep. 136; Polyb. 4, 36, 6; 21, 11, 2; Diod S 1, 16, 1; 1, 37, 3; 16, 85, 2 <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Χάρητα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Λυσικλέα</span>=Cares e Lisicles [são feitos generais]; Plut., Tib. Gracch. 825 [2, 3] <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Δροῦσον</span> = <span class=\"greek\">Δροῦσος</span>, Pyrrh. 395 [20, 1] <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Γάϊον</span> <span class=\"greek\">Φαβρίκιον</span> = <span class=\"greek\">Γάϊος</span> <span class=\"greek\">Φαβρίκιος</span>; Diog. L. 2, 43 <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Αἰσχύλον</span>=Ésquilo; 2, 105; EpArist 51; Philo, Vi. Cont. 15; Jos., Ant. 13, 187; 15, 370, C. Ap. 1, 17). <span class=\"greek\">οἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">Παῦλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:1a</a>, variante textual = <span class=\"greek\">Παῦλος</span> v. 1b.<br><br>ⓑ De tempo: aproximadamente, por volta de (Hdt., Thu., X. e outros; PGen 17, 10; PGiss 70, 7; Gen 15:12; Ex 11:4): <span class=\"greek\">περὶ</span> <span class=\"greek\">τρίτην</span> <span class=\"greek\">ὥραν</span> (Appian, Bell. Civ. 2, 45 §182; TestAbr A 5 p. 82, 11 [Stone p. 12] e B 6 p. 109, 27 [Stone p. 66]; Jos., Vi. 239; cf. 243; PSI 184, 5 <span class=\"greek\">χθὲς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἕκτην</span> <span class=\"greek\">ὥραν</span>) «por volta da terceira hora» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:3</a>. De modo semelhante, com as horas indicadas nos vv. 5f, 9; 27:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:3</a> (<span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὥραν</span> <span class=\"greek\">ἐνάτην</span>; ApcMos 17 <span class=\"greek\">περὶ</span> <span class=\"greek\">ὥραν</span>, <span class=\"greek\">ὅταν</span>), 9; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:6a</a>.<br><br>ⓒ De estar ocupado com alguma coisa (Just., D. 2, 5 <span class=\"greek\">χρόνον</span> <span class=\"greek\">ἐκτρίβειν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἐκεῖνα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μαθματα</span>; 8, 3 <span class=\"greek\">τῆς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">ὁρμῆς</span>; Tat. 27, 3; Ath. 17, 3): <span class=\"greek\">περισπᾶσθαι</span> (veja o verbete 2), <span class=\"greek\">θορυβάζεσθαι</span> <span class=\"greek\">περί</span> <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:40f</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τοιαῦτα</span> <span class=\"greek\">ἐργάται</span> «os trabalhadores ocupados com tais coisas» (veja <span class=\"greek\">ἐργάτης</span> 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:25</a>.<br><br>ⓓ Com relação ou referência a (Diod S 2, 18, 2 <span class=\"greek\">ἡ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἀρετή</span> = «sua valentia»; Lucian, Vit. Auct. 17 <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">μοιχείαν</span> <span class=\"greek\">νόμοι</span>; ApcEsdr 1:6 <span class=\"greek\">δικάσασθαι</span> … <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γένος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χριστιανῶν</span>; Jos., Ant. 5, 259; Mel., HE 4, 26, 13 <span class=\"greek\">σου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σπουδαῖον</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span>): <span class=\"greek\">ἀστοχεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:18</a>. <span class=\"greek\">ναυαγεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:19</a>. <span class=\"greek\">νοσεῖν</span> «ter um desejo mórbido por algo» (veja <span class=\"greek\">νοσέω</span>) 6:4. <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντα</span> «em todos os aspectos» Tit 2:7.—Pol 4:3; <span class=\"greek\">παράδοξον</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Ἰοῦστον</span> … <span class=\"greek\">γέγονος</span> «milagre ocorrido em relação a Justo» Papias (2:9). Sobre 2 Cl 17:2, veja <span class=\"greek\">ἀνάγω</span> 5.—<span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἐμέ</span> «minha situação, como estou passando» (Menand., Sam. 623 S. [Kö. 278]; UPZ 68, 6 [152 a.C.] <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Ἀπολλώνιον</span>; Just., A I, 54, 2 <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Χριστόν</span>; Tat. 8, 4 <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">σέ</span>; Jos., Ant. 2, 60) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:23</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπὰ</span> <span class=\"greek\">ἐπιθυμίαι</span> «desejos por outras coisas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:19</a>.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιάγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιάγω</span>, imperfeito <span class=\"greek\">περιῆγον</span>; futuro, 3.ª pessoa singular <span class=\"greek\">περιάξει</span> Is 28:27; 2.º aoristo <span class=\"greek\">περιήγαγον</span> (Eur., Hdt. e outros; inscrições, papiros, LXX, Philo).<br><br>① Levar ou trazer consigo, conduzir de um lugar para outro, transitivo (Eur., Hdt. e outros; inscrições, LXX, Joseph.), <span class=\"greek\">τινά</span> «alguém»: levar alguém consigo de um lugar a outro, tê-lo consigo (constantemente) ou como acompanhante (X., Cyr. 2, 2, 28; Demosth. 36, 45 <span class=\"greek\">τρεῖς</span> <span class=\"greek\">παῖδας</span> <span class=\"greek\">ἀκολούθους</span> <span class=\"greek\">π</span>.; Diod S 2, 38, 6 <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">πλῆθος</span> <span class=\"greek\">περιάγειν</span>; 17, 77, 6 códices <span class=\"greek\">τὰς</span> <span class=\"greek\">παλλακίδας</span> = «as concubinas»): <span class=\"greek\">ἀδελφὴν</span> <span class=\"greek\">γυναῖκα</span> <span class=\"greek\">π</span>. «levar consigo uma irmã (isto é, uma mulher cristã) como esposa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:5</a> (Diog. L. 6, 97: Crates, o cínico, leva consigo sua esposa, de pensamento semelhante ao seu, em suas viagens filosóficas).<br><br>② Viajar em diferentes direções, circular, percorrer, andar por vários lugares, intransitivo (Cebes 6, 3, códices; raro nesse sentido, mas veja L-S-J-M s.v. II [B-D-F §150; 308; Rob. 477].—Também intransitivo em Is 28:27), talvez «andar em volta» <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span> Hs 9, 11, 4. Acerca de um cego que tateia o caminho: «andar às apalpadelas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:11</a>. Com indicação do lugar: percorrer, andar por <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Γαλιλαίᾳ</span> «por toda a Galileia» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:23</a>. Com acusativo do território percorrido (PCairZen 33, 3 [257 a.C.] <span class=\"greek\">π</span>. <span class=\"greek\">πάντας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">παραδείσους</span>): <span class=\"greek\">τὰς</span> <span class=\"greek\">πόλεις</span> <span class=\"greek\">πάσας</span> «por todas as cidades» 9:35. <span class=\"greek\">τὰς</span> <span class=\"greek\">κώμας</span> <span class=\"greek\">κύκλῳ</span> «pelas aldeias vizinhas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:6</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ξηράν</span> «percorrer mar e terra» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:15</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιαιρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιαιρέω</span>, futuro <span class=\"greek\">περιελῶ</span> LXX; 2.º aoristo <span class=\"greek\">περιεῖλον</span> LXX, infinitivo <span class=\"greek\">περιελεῖν</span>, particípio <span class=\"greek\">περιελών</span>. Médio: futuro, 3.ª pessoa do plural <span class=\"greek\">περιελοῦνται</span> (EpJer 57); 2.º aoristo, 3.ª pessoa singular <span class=\"greek\">περιείλατο</span> (Jon 3:6; GJs 2:4). Passivo: imperfeito, 3.ª pessoa singular <span class=\"greek\">περιῃρεῖτο</span>; futuro, 3.ª pessoa singular <span class=\"greek\">περιαιρεθήσεται</span> LXX; perfeito, 3.ª pessoa do plural <span class=\"greek\">περιῄρηνται</span> (TestJob 43, 4) (Hom. e outros; papiros, LXX).<br><br>① Tirar de em torno de alguma coisa, retirar, remover (<span class=\"greek\">τείχη</span>: Hdt. 3, 159; 6, 46; Thu. 1, 108, 3; <span class=\"greek\">δέρματα</span> <span class=\"greek\">σωμάτων</span> Pla., Polit. 288e; <span class=\"greek\">τὸν</span> <span class=\"greek\">χιτῶνα</span> Aristot., HA 5, 32): <span class=\"greek\">Ἅννα</span> … <span class=\"greek\">περιείλατο</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πενθικά</span> «Ana retirou suas vestes de luto» GJs 2:4. No passivo, também em sentido geral, «ser retirado» (PTebt 5, 146; 165 [118 a.C.]; Jos., Bell. 1, 179, Ant. 20, 212): <span class=\"greek\">περιαιρεῖται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κάλυμμα</span> «o véu é removido» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:16</a> (cf. Ex 34:34). <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀγκύρας</span> <span class=\"greek\">περιελόντες</span> <span class=\"greek\">εἴων</span> «soltaram ou desprenderam as âncoras e deixaram-nas ir» (isto é, soltaram os cabos que prendiam as âncoras, abandonando-as) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:40</a>.—Caso a leitura textual de 28:13 <span class=\"greek\">περιελόντες</span>, em uso absoluto, deva ser mantida, o sentido «pusemo-nos a caminho» requer que se subentenda <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀγκύρας</span> = «levantamos âncora» (assim NRSV; AAcworth, JTS 24, ’73, 193, favorece essa leitura, mas traduz «contornamos» = fizemos uma mudança de direção). Blass, porém, ad loc., rejeita essa leitura, e o sentido aqui atribuído a ela é reconhecidamente conjectural (Metzger ad loc.). Haenchen propõe <span class=\"greek\">παρελθόντες</span> «navegando ao longo (da costa)». REB: «navegamos pela costa» (talvez leitura <span class=\"greek\">περιελθόντε</span>, variante textual [assim NRB «navegamos ao redor», veja The Greek NT, ed. RTasker ’64]; essa variante também HConzelmann, Hermeneia: Acts, «navegamos ao longo da costa»).<br><br>② Acabar com, eliminar, retirar (Ex 8:4, 27): <span class=\"greek\">ἁμαρτίας</span> «pecados» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:11</a> (a «remoção» do pecado por Deus também é mencionada em 1 Ch 21:8; Zeph 3:11, 15. Cf. PCairZen 147, 3 [256 a.C.] <span class=\"greek\">π</span>. = «cancelar um registro, um direito»; e, para o uso figurado, também M. Ant. 12, 2 <span class=\"greek\">τὸν</span> <span class=\"greek\">πολὺν</span> <span class=\"greek\">περισπασμὸν</span> <span class=\"greek\">σεαυτοῦ</span> <span class=\"greek\">περιαιρήσεις</span>; Alciphron 2, 25, 2 <span class=\"greek\">φόβον</span>; Diog. L. 6, 7: tornar desnecessário desaprender [alguma coisa]; 6, 10). Passivo: <span class=\"greek\">περιῃρεῖτο</span> <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">πᾶσα</span> «toda esperança era gradualmente abandonada» (imperfeito) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:20</a>.—M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιάπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιάπτω</span>, 1.º aoristo, 3.ª pessoa do plural <span class=\"greek\">περιῆψαν</span> 3 Macc 3:7; particípio <span class=\"greek\">περιάψας</span>; infinitivo perfeito passivo <span class=\"greek\">περιῆφθαι</span> (EpArist 159) (Pind. e outros; PTebt 735, 11 [II a.C.]; TestSol P [PVindob 18, 37]; Philo; Jos., Ant. 12, 260), acender, atear fogo, <span class=\"greek\">πῦρ</span> (Phalaris, Ep. 122, 2 Herch., variante textual) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:55</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιαστράπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιαστράπτω</span> (<span class=\"greek\">ἀστράπτω</span> «relampejar», como um relâmpago), 1.º aoristo <span class=\"greek\">περιήστραψα</span> (Galen: CMG V 9, 1 p. 392, 2; 4 Macc 4:10; escritores cristãos [Lampe s.v.], bem como Rhet. Gr. I 616, 1).<br><br>① Emitir luz intensa sobre a área ao redor de uma pessoa, brilhar ao redor, transitivo, <span class=\"greek\">τινά</span> «alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:3</a>; 22:6 D.<br><br>② Brilhar intensamente, reluzir (ao redor), intransitivo (Psellus p. 37, 19), <span class=\"greek\">περί</span> <span class=\"greek\">τινα</span> «ao redor de alguém» 22:6. O centro da ação é Paulo.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιβάλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιβάλλω</span>, futuro <span class=\"greek\">περιβαλῶ</span>; 2.º aoristo <span class=\"greek\">περιέβαλον</span>, imperativo <span class=\"greek\">περίβαλε</span>, infinitivo <span class=\"greek\">περιβαλεῖν</span>. Médio: futuro <span class=\"greek\">περιβαλοῦμαι</span>; 2.º aoristo <span class=\"greek\">περιεβαλόμην</span>. Passivo: particípio aoristo plural <span class=\"greek\">περιβληθέντες</span> Wsd 19:17; particípio perfeito <span class=\"greek\">περιβεβλημένος</span> (Hom.+).<br><br>① Cercar mediante a construção de alguma coisa ao redor, colocar em volta, acerca de cidade circundada (<span class=\"greek\">περιβ</span>. para a construção de muros ao redor de uma cidade pelos habitantes: Aelian, VH 6, 12; Palaeph. 17; SIG 344, 14; Pr 28:4. Sobre um terreno cercado: POxy 707, 32): <span class=\"greek\">περιβαλοῦσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐχθροί</span> <span class=\"greek\">σου</span> <span class=\"greek\">χάρακά</span> <span class=\"greek\">σοι</span> «teus inimigos levantarão um aterro ao teu redor» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:43</a>, variante textual (em lugar de <span class=\"greek\">παρεμβαλοῦσιν</span>; cf. Nearchus of Crete [c. 300 a.C.]: 133 Fgm. 1, 33, 10 Jac.; Arrian, Anab. 5, 23, 6 <span class=\"greek\">Ἀλέξανδρος</span> <span class=\"greek\">χάρακι</span> <span class=\"greek\">περιβάλλει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλιν</span>; Ezk 4:2; veja <span class=\"greek\">χάραξ</span>).<br><br>② Vestir, colocar uma peça de roupa, especialmente quanto a artigos de vestuário.<br><br>ⓐ <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> «alguma coisa em alguém» (TestLevi 8:7; cf. Plut., Popl. 99 [5, 3] <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τραχήλοις</span>; Ps.-Clem., Hom. 8, 22); daí (ou de d abaixo) o médio <span class=\"greek\">περιβάλλομαί</span> <span class=\"greek\">τι</span> «vestir, colocar alguma coisa (em si próprio)» (Hom. e outros; 1 Km 28:8; 4 Km 19:1; Jon 3:8; Is 37:1; TestAbr A 17 p. 99, 14 [Stone p. 46]; TestNapht 6:8; JosAs 3:9; 15:10): <span class=\"greek\">τί</span> <span class=\"greek\">περιβαλώμεθα</span>; «com que nos vestiremos?» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:31</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:8</a>. <span class=\"greek\">περιβέβλημαί</span> <span class=\"greek\">τι</span> «ter-se vestido de alguma coisa, usá-la como vestimenta» (EpJer 11; Da 12:6f; AscIs 2:10; Jos., Ant. 8, 207; Mel., P. 19, 132): <span class=\"greek\">νεανίσκον</span> <span class=\"greek\">περιβεβλημένον</span> <span class=\"greek\">στολὴν</span> <span class=\"greek\">λευκήν</span> «um jovem vestido de veste branca» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:5</a> (Lucian, Philops. 25, acerca de mensageiro celestial: <span class=\"greek\">νεανίας</span> <span class=\"greek\">λευκὸν</span> <span class=\"greek\">ἱμάτιον</span> <span class=\"greek\">περιβεβλημένος</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:9</a>, 13; 11:3; 17:4; 18:16; 19:13; GPt 13:55. <span class=\"greek\">ἄγγελον</span> <span class=\"greek\">περιβεβλημένον</span> <span class=\"greek\">νεφέλην</span> «um anjo envolto em uma nuvem» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:1</a>. <span class=\"greek\">γυνὴ</span> <span class=\"greek\">περιβεβλημένη</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span> «uma mulher revestida do sol» 12:1. <span class=\"greek\">περιβεβλημένος</span> <span class=\"greek\">σινδόνα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">γυμνοῦ</span> «que usava (nada além de) um pano de linho sobre o corpo nu» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:51</a>.<br><br>ⓑ <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> «vestir alguém com alguma coisa» (Eur. e outros): <span class=\"greek\">περιβεβλημένη</span> <span class=\"greek\">πορφυρᾷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κοκκίνῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:4</a>, texto recebido (leitura erasmiana; cf. Pla., Critias 116c <span class=\"greek\">περιβεβλημένος</span> <span class=\"greek\">περιβόλῳ</span> <span class=\"greek\">χρυσῷ</span>; 3 Km 11:29).<br><br>ⓒ <span class=\"greek\">περιβάλλεσθαι</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> «vestir-se com alguma coisa» (Dt 22:12; 1 Ch 21:16; Ps 44:10, 14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:5</a>; 4:4.<br><br>ⓓ Com duplo acusativo, <span class=\"greek\">τινά</span> <span class=\"greek\">τι</span> «colocar alguma coisa sobre alguém» (Ezk 27:7.—B-D-F §155, 5; Rob. 483): <span class=\"greek\">ἱμάτιον</span> <span class=\"greek\">πορφυροῦν</span> <span class=\"greek\">περιέβαλον</span> <span class=\"greek\">αὐτόν</span> «colocaram nele uma veste de púrpura» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:2</a>. Cf. GPt 3:7. O acusativo de pessoa é facilmente subentendido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:11</a>.<br><br>ⓔ Sem referência à peça de roupa, <span class=\"greek\">περιβάλλω</span> <span class=\"greek\">τινά</span> «vestir alguém» (Ezk 18:7, 16; TestJob 39, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:36</a>, 43; B 3:3 (Is 58:7); com acusativo subentendido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:38</a>. No médio <span class=\"greek\">περιβάλλομαι</span> «vestir-se» (Hg 1:6; Lev 13:45) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:18</a>.<br><br>③ Envolver alguém em tortura, submetendo a pessoa ao infortúnio (Eur. e outros; PSI 330, 7 [258/257 a.C.]; 3 Macc 6:26 <span class=\"greek\">τοὺς</span> … <span class=\"greek\">περιέβαλεν</span> <span class=\"greek\">αἰκίαις</span>; Jos., Ant. 2, 276; cf. EpArist 208; 167; Tat. 19, 1 <span class=\"greek\">θανάτῳ</span> <span class=\"greek\">περιβαλεῖν</span>), extensão figurada do sentido primário «colocar em redor»: <span class=\"greek\">τοὺς</span> <span class=\"greek\">δουλεύοντας</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αἰκίαν</span> <span class=\"greek\">περιβαλεῖν</span> «tratar cruelmente aqueles que servem a Deus» 1 Cl 45:7.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιβλέπω</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιβλέπω</span> (Soph., X., Pla. e outros; BGU 1097, 3; LXX; Jos., Bell. 1, 627 e outros), em nossa literatura somente na voz média <span class=\"greek\">περιβλέπομαι</span> (Polyb.; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 55, 18 V. e outros; LXX; TestJos 7:1; cf. B-D-F §316, 1; Rob. 809; 813), imperfeito, 3.ª pessoa singular <span class=\"greek\">περιεβλέπετο</span>; futuro, 3.ª pessoa singular <span class=\"greek\">περιβλέψεται</span> Job 7:8; 1.º aoristo, 3.ª pessoa singular <span class=\"greek\">περιεβλέψατο</span> 3 Km 21:40; particípio <span class=\"greek\">περιβλεψάμενος</span>.<br><br>① Lançar olhares ou olhar em diversas direções ao redor, olhar em volta (para), absolutamente (Diod S 16, 32, 2; Plut., Cato Min. 777 [37; 8]; Ex 2:12; 3 Km 21:40) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:8</a>; 10:23. Seguido de infinitivo de finalidade (B-D-F §392, 3; cf. Rob. 989 f): <span class=\"greek\">περιεβλέπετο</span> <span class=\"greek\">ἰδεῖν</span> «olhava (ou continuava olhando) ao redor para ver» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:32</a>. Com acusativo de pessoa (Polyb. 9, 17, 6; Job 7:8): <span class=\"greek\">περιβλεψάμενος</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">καθημένους</span> «olhou em volta para os que estavam sentados ao redor dele» etc. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:34</a>. Cf. v. 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:10</a>. <span class=\"greek\">περιβλεψάμενος</span> <span class=\"greek\">πάντα</span> «quando olhou em volta para tudo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:11</a>. <span class=\"greek\">περιέβλεπεν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δεξιὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀριστερά</span> «ela olhava para a direita e para a esquerda» GJs 11:1. <span class=\"greek\">περιβλεψάμενος</span> [<span class=\"greek\">γὰρ</span> <span class=\"greek\">κύκλῳ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λέων</span>] AcPl Ha 4, 29.<br><br>② Procurar atentamente, estar à espreita, buscar, caçar, com enfraquecimento do sentido literal (com acusativo Epict. 3, 22, 65; M. Ant. 7, 55; Lucian, Vit. Auct. 12): <span class=\"greek\">περιβλέπονται</span> <span class=\"greek\">τίνα</span> <span class=\"greek\">ἐκδύσωσιν</span> «procuram alguém a quem possam saquear» B 10:4. <span class=\"greek\">Ἐλισάβεδ</span> … <span class=\"greek\">περιεβλέπετο</span> <span class=\"greek\">ποῦ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἀποκρύψῃ</span> «Isabel procurava um lugar onde pudesse esconder (João)» GJs 22:3.—M-M s.v. <span class=\"greek\">περιβλέπομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0280-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">περιβόητος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">περιβόητος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">βοάω</span>; Soph., Thu. e outros), referente à condição de ser aclamado por toda parte, muito conhecido, amplamente afamado, célebre (assim Demosth. 34, 29; Menand., Fgm. 402, 3 Kö.; Plut., Ages. 609c [24, 5], Themist. 119 [15, 4]; 2 Macc 2:22; Philo, Mos. 2, 284 <span class=\"greek\">εὐσέβεια</span>; Jos., Ant. 6, 165, C. Ap. 1, 315): <span class=\"greek\">φιλαδελφία</span> 1 Cl 47:5; (com <span class=\"greek\">σεμνός</span> e <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">ἀξιαγάπητος</span>) <span class=\"greek\">ὄνομα</span> 1:1.—DELG s.v. <span class=\"greek\">βοή</span>.</p></section></article>"};
